    "所选 Opti 版本未找到本地缓存包，请选择在线下载源或选择其他版本。": "이 Opti 버전의 로컬 패키지를 찾지 못했습니다. 온라인 다운로드 소스나 다른 버전을 선택하세요.",
    "本地安装包不存在，请重新选择安装来源。": "로컬 패키지가 없습니다. 설치 소스를 다시 선택하세요.",
    "撤销未完成的 Opti 操作，保留原文件和回退记录。": "원본 파일과 롤백 기록을 유지하면서 완료되지 않은 Opti 작업을 취소합니다.",
    "从本地安装": "로컬 패키지에서 설치",
    "已找到本地安装包，可直接安装。": "로컬 패키지를 찾았습니다. 다운로드 없이 설치할 수 있습니다.",
    "仅首次下载；之后所有游戏复用本地安装包。": "한 번만 다운로드하면 모든 게임에서 로컬 패키지를 재사용합니다.",
    "先选择游戏主程序，确认后再显示安装和设置。": "게임 실행 파일을 먼저 선택하면 설치 및 설정 메뉴가 표시됩니다.",
    "必选：选择实际运行的游戏主程序。": "필수: 실제로 게임을 실행하는 실행 파일을 선택하세요.",
    "未找到可用的游戏主程序，请检查游戏安装。": "사용할 수 있는 게임 실행 파일을 찾지 못했습니다. 게임 설치를 확인하세요.",
    "正在准备 Opti 安装…": "Opti 설치 준비 중…",
    "正在临时关闭 XMX，以安装 Opti…": "Opti를 설치하기 위해 XMX를 일시적으로 끄는 중…",
    "Opti 已安装，正在恢复 XMX…": "Opti를 설치했습니다. XMX 복원 중…",
    "Opti 已安装，XMX 已恢复；下次启动游戏生效。": "Opti를 설치하고 XMX를 복원했습니다. 다음 게임 실행부터 적용됩니다.",
    "安装流程未完成，请按当前状态完成或恢复：": "설치가 완료되지 않았습니다. 현재 작업을 완료하거나 복원하세요: ",
    "游戏正在运行，请先退出游戏再安装或更换 Opti。": "게임이 실행 중입니다. Opti를 설치하거나 변경하기 전에 게임을 종료하세요.",
    "安装时自动暂时关闭 XMX，完成后恢复；请先退出游戏。": "설치 중에는 XMX를 일시적으로 끄고 완료 후 복원합니다. 먼저 게임을 종료하세요.",
    "安装所选版本，保留回退备份；请先退出游戏。": "롤백용 백업을 보관하고 선택한 버전을 설치합니다. 먼저 게임을 종료하세요.",
    "修复并安装所选版本": "선택한 버전으로 복구",
    "保留现有文件并建立回退备份。": "기존 파일을 유지하고 롤백용 백업을 만듭니다.",
    "没有待完成的 Opti 启动设置。": "대기 중인 Opti 실행 설정이 없습니다.",
    "Opti 安装版本": "설치할 Opti 버전",
    "重新准备 Opti 10 和 FSR 组件，并重置超分与帧生成；之后重新选择 FSR。": "Opti 10과 FSR 구성 요소를 다시 준비하고 업스케일링 및 프레임 생성을 초기화합니다. 이후 FSR을 선택하세요.",
    "当前已安装：": "현재 설치된 버전: ",
    "10.0 预览版（FSR 4.1 XMX）": "10.0 미리보기(FSR 4.1 XMX)",
    "请先关闭 XMX；安装旧版后 FSR 4.1 XMX 需要重新准备 Opti 10。": "먼저 XMX를 끄세요. 이전 버전을 설치한 뒤 FSR 4.1 XMX를 사용하려면 Opti 10을 다시 준비해야 합니다.",
    "安装旧版后 FSR 4.1 XMX 需要重新准备 Opti 10；保留回退备份。": "FSR 4.1 XMX를 사용하려면 Opti 10을 다시 준비해야 합니다. 롤백용 백업은 유지됩니다.",
    "选择后自动保存；请先退出游戏。": "선택한 값은 자동으로 저장됩니다. 먼저 게임을 종료하세요.",
    "正在自动保存设置…": "설정 자동 저장 중…",
    "设置已自动保存，下次启动游戏生效。": "설정을 자동으로 저장했습니다. 다음 게임 실행부터 적용됩니다.",
    "游戏正在运行，请先退出游戏再更改设置。": "게임이 실행 중입니다. 설정을 변경하기 전에 게임을 종료하세요.",
    "FSR 4.1.2 Lite XMX 已就绪；从 Steam 启动游戏即可。": "FSR 4.1.2 Lite XMX가 준비되었습니다. Steam에서 게임을 실행하세요.",
    "重新选择 FSR 后会自动准备此游戏并保存。": "FSR을 다시 선택하면 이 게임을 준비하고 자동으로 저장합니다.",
    "FSR 需要 XMX；重新选择 FSR 会自动开启 XMX。": "FSR에는 XMX가 필요합니다. FSR을 다시 선택하면 XMX가 자동으로 켜집니다.",
    "重新选择 FSR 会自动准备组件并开启 XMX。": "FSR을 다시 선택하면 구성 요소를 준비하고 XMX를 자동으로 켭니다.",
    "打开时优先选择正在运行的游戏，也可手动切换。": "기본적으로 실행 중인 게임을 엽니다. 다른 게임을 직접 선택할 수도 있습니다.",
    "仅限 Intel；更改前请退出游戏。": "Intel 전용입니다. 변경하기 전에 게임을 종료하세요.",
