    "默认官方源；镜像由第三方提供。": "기본값은 공식 소스이며, 타사 미러도 사용할 수 있습니다.",
    "保留文件并建立回退备份。": "파일을 유지하고 롤백용 백업을 만듭니다.",
    "开启 Opti 注入后生效。": "Opti 주입을 켜면 적용됩니다.",
    "插帧倍率": "프레임 생성 배율",
    "游戏原生控制": "게임에서 제어",
    "原生": "네이티브",
    "选择游戏支持的帧生成类型。": "게임에서 지원하는 프레임 생성 방식을 선택하세요.",
    "启用 Intel XMX 执行路径；帧生成仍需游戏、运行时和 Proton 支持。": "Intel XMX 경로를 사용합니다. 프레임 생성을 사용하려면 게임, 런타임, Proton도 지원해야 합니다.",
    "XeSS FG 倍率（实验）": "XeSS FG 배율(실험적)",
    "仅用于 Opti XeSS FG 输出。实际倍率取决于运行时支持；原生 XeSS FG 请在游戏内设置。": "Opti XeSS FG 출력에 적용됩니다. 실제 배율은 런타임에서 지원하는 값에 따라 달라집니다. 기본 XeSS FG는 게임에서 설정하세요.",
