    "设置保存未完成，已保留恢复记录；请先恢复上次设置：": "설정을 모두 저장하지 못했습니다. 복구 기록을 보관했습니다. 먼저 이전 설정을 복구하세요: ",
    "设置恢复未完成，已保留恢复记录；请重试恢复上次设置：": "설정 복구를 완료하지 못했습니다. 기록을 보관했습니다. 복구를 다시 시도하세요: ",
