    "游戏程序已经变化，请重新打开插件": "게임 실행 파일이 변경되었습니다. 플러그인을 다시 열고 계속하세요.",
    "XMX 状态已变化，请重新打开插件": "XMX 상태가 변경되었습니다. 플러그인을 다시 열고 계속하세요.",
