    "FSR 4.1.2 Lite XMX": "FSR 4.1.2 Lite XMX",
    "XMX 开启时可选择 XeSS 或 FSR 4.1.2 Lite；先退出游戏，保存后下次启动生效。": "XMX를 켠 상태에서 XeSS 또는 FSR 4.1.2 Lite를 선택하세요. 먼저 게임을 종료하면 다음 실행부터 변경 사항이 적용됩니다.",
    "FSR 4.1.2 Lite 通过 XMX 兼容组件运行；保存时会准备此游戏。": "FSR 4.1.2 Lite는 XMX 호환 구성 요소를 사용합니다. 저장하면 이 게임을 준비합니다.",
    "FSR 模型包已就绪；保存时会为此游戏准备 Opti 10 和模型。": "FSR 모델 패키지가 준비되었습니다. 저장하면 이 게임에서 사용할 Opti 10과 모델을 준비합니다.",
    "此游戏的 FSR 文件已准备；保存时会刷新 XMX 兼容组件。": "이 게임의 FSR 파일이 준비되었습니다. 저장하면 XMX 호환 구성 요소를 새로 고칩니다.",
    "FSR 4.1.2 Lite XMX 已就绪；退出游戏后保存设置并从 Steam 重新启动。": "FSR 4.1.2 Lite XMX가 준비되었습니다. 게임을 종료하고 설정을 저장한 다음 Steam에서 다시 실행하세요.",
    "FSR 需要 XMX；保存后会自动开启 XMX，退出游戏后从 Steam 启动。": "FSR에는 XMX가 필요합니다. 저장하면 XMX가 켜집니다. 게임을 종료하고 Steam에서 다시 실행하세요.",
    "FSR 需要 XMX；保存时会为此游戏准备 FSR 并自动开启 XMX。": "FSR에는 XMX가 필요합니다. 저장하면 이 게임의 FSR을 준비하고 XMX를 켭니다.",
    "导入 FSR 模型包": "FSR 모델 패키지 가져오기",
    "当前插件后台不支持 FSR 模型导入，请更新插件。": "이 플러그인 백엔드는 FSR 모델 가져오기를 지원하지 않습니다. 플러그인을 업데이트하세요.",
    "请导入本地 FSR 模型包。": "로컬 FSR 모델 패키지를 가져옵니다.",
    "正在选择 FSR 模型包…": "FSR 모델 패키지 선택 중…",
    "请选择 ZIP 格式的 FSR 模型包。": "ZIP 형식의 FSR 모델 패키지를 선택하세요.",
    "FSR 模型包已导入并验证。": "FSR 모델 패키지를 가져와 검증했습니다.",
    "FSR 模型包尚未就绪。": "FSR 모델 패키지가 아직 준비되지 않았습니다.",
    "启动项已变化，请重新打开插件后恢复 XMX，再保存 FSR。": "실행 옵션이 변경되었습니다. FSR 설정을 저장하기 전에 플러그인을 다시 열고 XMX를 복원하세요.",
    "FSR XMX 兼容组件尚未就绪，请重新打开插件后重试。": "FSR XMX 호환 구성 요소가 준비되지 않았습니다. 플러그인을 다시 열고 시도하세요.",
    "DLSS（需要支持的显卡）": "DLSS(지원 GPU 필요)",
    "帧生成输出": "프레임 생성 출력",
    "这是 Opti 的输出；XeFG 输入尚未实现。原生 XeSS FG 可关闭 Opti 注入测试。": "Opti의 출력 방식입니다. XeFG 입력은 구현되지 않았습니다. 기본 XeSS FG를 테스트하려면 Opti 주입을 끄세요.",
    "Opti 注入已关闭；这里的设置将在重新开启后生效。": "Opti 주입이 꺼져 있습니다. 다시 켜면 이 설정이 적용됩니다.",
    "游戏原生（不接管）": "네이티브(FG 가로채기 없음)",
    "FSR 帧生成": "FSR 프레임 생성",
    "XeSS 帧生成（实验）": "XeSS 프레임 생성(실험적)",
    "游戏 FG 类型": "게임의 FG 입력",
    "选择游戏实际支持的类型，并在游戏里开启对应帧生成。无原生 FG 才选超分输入。": "지원되는 입력을 선택한 뒤 게임에서 켜세요. 게임에 기본 FG 기능이 없으면 업스케일러 입력을 사용하세요.",
    "无原生 FG：使用超分输入": "기본 FG 없음: 업스케일러 입력 사용",
    "显卡伪装": "GPU 식별 정보 위장",
    "XMX 开启时保留真实 Intel 身份。": "XMX는 실제 Intel GPU 식별 정보를 유지합니다.",
    "实验兼容选项；改身份不保证解锁功能。": "실험적 호환성 옵션입니다. GPU를 위장해도 기능 지원을 보장하지 않습니다.",
    "真实显卡（推荐）": "실제 GPU(권장)",
    "保存设置": "설정 저장",
    "恢复默认": "기본값으로 재설정",
    "恢复 XeSS、真实显卡、由游戏管理帧生成；先退出游戏。": "XeSS, 실제 GPU 식별 정보, 기본 FG를 복원합니다. 먼저 게임을 종료하세요.",
    "Opti 版本": "Opti 버전",
    "0.9.4（当前稳定版）": "0.9.4(안정 버전)",
    "0.7.9（兼容旧版）": "0.7.9(이전 버전 호환)",
    "先关闭 XMX，再更换 Opti 版本。": "Opti 버전을 변경하기 전에 XMX를 끄세요.",
    "开启 Opti 注入后可更换版本；保留回退备份。": "버전을 바꾸기 전에 Opti 주입을 켜세요. 롤백용 백업은 보관합니다.",
    "安装所选版本": "선택한 버전 설치",
    "回退上次操作": "마지막 작업 취소",
    "撤销上次安装、迁移或卸载；需先关闭 XMX。": "마지막 설치, 마이그레이션, 전환 또는 제거를 취소합니다. 먼저 XMX를 끄세요.",
    "卸载 Opti": "Opti 제거",
    "确认卸载 Opti": "Opti 제거 확인",
    "卸载本插件管理的 Opti 文件并恢复原文件；需先关闭 XMX。": "관리되는 Opti 파일을 제거하고 원본을 복원합니다. 먼저 XMX를 끄세요.",
    "操作失败": "작업 실패",
    "Opti2XMX：未完成": "Opti2XMX: 완료되지 않음",
    "读取 Steam 启动项超时": "Steam 실행 옵션을 읽는 중 시간 초과",
    "启动项刚被其他工具修改，请重新打开插件后重试": "다른 도구에서 실행 옵션을 변경했습니다. 플러그인을 다시 열고 시도하세요.",
    "Steam 启动项写入尚未确认，请使用继续开启或恢复": "Steam에서 실행 옵션을 확인하지 못했습니다. 설정을 계속하거나 복원하세요.",
    "正在读取游戏列表…": "게임 목록 로드 중…",
