    "启动项已被其他工具修改，请检查后再试。": "다른 도구에서 실행 옵션을 변경했습니다. 옵션을 확인한 후 다시 시도하세요.",
    "发现多个游戏程序，请在下面确认一次。": "게임 실행 파일이 여러 개 있습니다. 아래에서 하나를 선택하세요.",
