    "上次设置未完成，请先点击恢复。": "이전 설정을 완료하지 못했습니다. 먼저 복원하세요.",
    "已开启。直接从 Steam 启动游戏即可。": "켜졌습니다. Steam에서 게임을 실행하세요.",
    "已关闭，原文件和启动项已恢复。": "꺼졌습니다. 원본 파일과 실행 옵션을 복원했습니다.",
    "XMX 已开启": "XMX 켜짐",
    "XMX 已关闭": "XMX 꺼짐",
    "上次设置未完成，请用下面的按钮继续或恢复。": "설정이 완료되지 않았습니다. 아래 버튼으로 계속하거나 복원하세요.",
    "启动设置已变化。打开开关可重新应用；也可以恢复原配置。": "실행 옵션이 변경되었습니다. 스위치를 켜서 다시 적용하거나 원래 설정을 복원할 수 있습니다.",
    "已就绪，打开开关即可。启用或关闭前请先退出游戏。": "켤 준비가 되었습니다. 전환하기 전에 게임을 종료하세요.",
    "正在开启 Opti 注入…": "Opti 주입을 켜는 중…",
    "正在关闭 Opti 注入，保留 XMX…": "XMX를 유지하면서 Opti 주입을 끄는 중…",
    "Opti 注入已开启，下次启动生效。": "Opti 주입을 켰습니다. 다음 실행부터 적용됩니다.",
    "Opti 注入已关闭；XMX 设置保留，使用游戏原生功能。": "Opti 주입을 껐습니다. XMX 설정을 유지하고 게임의 기본 기능을 사용합니다.",
    "正在下载并安装 Opti，请稍候…": "Opti 다운로드 및 설치 중…",
    "正在处理 Opti 配置…": "Opti 설정 업데이트 중…",
    "启动项已变化，请检查后重试": "실행 옵션이 변경되었습니다. 확인한 후 다시 시도하세요.",
    "Opti 操作完成，下次启动游戏生效。": "Opti 설정이 완료되었습니다. 다음 실행부터 적용됩니다.",
    "Opti 配置已完成": "Opti 설정 완료",
    "正在恢复推荐默认设置…": "권장 기본값으로 복원하는 중…",
    "正在保存设置…": "설정 저장 중…",
    "设置已保存，下次启动游戏生效。": "설정을 저장했습니다. 다음 실행부터 적용됩니다.",
    "正在切换 Opti 覆盖层…": "Opti 오버레이 전환 중…",
    "已发送覆盖层快捷键。": "오버레이 단축키를 보냈습니다.",
    "游戏仍在运行。请从 Steam 退出游戏，再操作 XMX 开关。": "게임이 아직 실행 중입니다. 스위치를 바꾸기 전에 Steam에서 게임을 종료하세요.",
    "游戏仍在运行，请退出后重试。": "게임이 아직 실행 중입니다. 종료한 후 다시 시도하세요.",
    "Opti 注入已关闭，当前使用游戏原生功能": "Opti 주입이 꺼져 있어 게임의 기본 기능을 사용합니다.",
    "请先启动选中的游戏，再打开面板": "오버레이를 열기 전에 선택한 게임을 실행하세요.",
    "未找到该游戏的可见窗口，请回到游戏后重试": "이 게임의 표시 창을 찾지 못했습니다. 게임으로 돌아가 다시 시도하세요.",
    "此游戏已有其他 XMX 配置，需要先迁移后才能用此开关。": "이 게임에 다른 XMX 설정이 있습니다. 이 스위치를 사용하기 전에 기존 설정을 이전하세요.",
    "XMX 运行组件未就绪。": "XMX 런타임 구성 요소가 준비되지 않았습니다.",
    "请先选择要运行的游戏程序。": "먼저 게임 실행 파일을 선택하세요.",
    "选择与 Steam 启动选项一致的版本。": "Steam 실행 옵션에서 사용하는 버전을 선택하세요.",
    "修复安装 Opti 0.9.4": "Opti 0.9.4 설치 복구",
    "缺少注入文件；备份现有文件后重新安装，可回退。": "인젝터가 없습니다. 기존 파일을 백업한 뒤 재설치하세요. 롤백할 수 있습니다.",
    "游戏已有注入文件，请先迁移或处理冲突：": "인젝터가 이미 있습니다. 먼저 이전하거나 충돌을 해결하세요: ",
    "请先从 Steam 用 Proton 启动游戏一次，退出后重新打开插件。": "이 게임을 Proton으로 한 번 실행한 뒤 종료하고 플러그인을 다시 여세요.",
    "尚未发现 XeSS。请先为此游戏安装 OptiScaler 并运行一次，然后重新打开插件。": "XeSS를 찾지 못했습니다. 이 게임에 OptiScaler를 설치하고 한 번 실행한 후 플러그인을 다시 여세요.",
    "未识别到可接入的游戏程序，请检查游戏安装。": "호환되는 실행 파일을 찾지 못했습니다. 게임 설치를 확인하세요.",
    "OptiScaler 文件不完整，需要同目录的 dxgi.dll 和 libxess.dll。": "OptiScaler 설치가 불완전합니다. dxgi.dll과 libxess.dll은 실행 파일과 같은 폴더에 있어야 합니다.",
    "请先开启 Opti 注入，再更换版本": "버전을 바꾸기 전에 Opti 주입을 켜세요.",
    "请先关闭 XMX，再安装、回退或卸载 Opti": "Opti를 설치하거나 롤백 또는 제거하기 전에 XMX를 끄세요.",
    "上次操作待完成，请先完成启动项设置或回退": "이전 작업이 대기 중입니다. 실행 설정을 완료하거나 롤백하세요.",
    "文件已被其他工具修改，请先处理冲突：": "다른 도구가 파일을 변경했습니다. 먼저 충돌을 해결하세요: ",
    "操作中断，备份已保存，请点击回退上次操作": "작업이 중단되었습니다. 백업을 저장했습니다. 마지막 작업 취소를 사용하세요.",
    "请选择支持的版本和下载源": "지원되는 버전과 다운로드 소스를 선택하세요.",
    "下载源没有返回 7z 安装包，请切换下载源": "다운로드 소스가 7z 패키지를 반환하지 않았습니다. 다른 소스를 선택하세요.",
    "安装包 DLL 格式无效：": "패키지의 DLL 형식이 유효하지 않습니다: ",
