    "请先启动游戏一次以创建 Proton 环境": "Proton 접두사를 만들려면 먼저 게임을 한 번 실행하세요.",
    "Steam 启动项与 XMX 记录不一致": "Steam 실행 옵션이 XMX 기록과 일치하지 않습니다.",
    "检测到自定义启动项，保留现场，请先处理冲突": "사용자 지정 실행 옵션은 그대로 두었습니다. 먼저 충돌을 해결하세요.",
    "不修改符号链接：": "심볼릭 링크는 수정할 수 없습니다: ",
    "文件不可安全修改：": "파일을 안전하게 변경할 수 없습니다: ",
    "已存在 Opti，请先迁移现有安装": "Opti가 이미 설치되어 있습니다. 먼저 기존 설치를 이전하세요.",
