    "请先关闭 XMX 再回退 Opti": "Opti를 롤백하기 전에 XMX를 끄세요.",
    "启动项已被外部修改": "다른 도구가 실행 옵션을 변경했습니다.",
    "文件已有后续改动，不能覆盖：": "그 이후 파일이 변경되어 덮어쓸 수 없습니다: ",
