    "无效设置投影路径": "설정 적용 경로가 유효하지 않습니다.",
    "设置格式备份与保存值不一致，保留现场": "설정 형식의 백업이 저장된 값과 일치하지 않습니다. 파일을 그대로 두었습니다.",
    "设置格式备份已有后续改动，保留现场": "설정 형식의 백업이 나중에 변경되어 파일을 그대로 두었습니다.",
    "设置文件在备份期间变化，保留现场": "백업 중 설정 파일이 변경되어 그대로 두었습니다.",
