    "XMX 开启时保留 XeSS / FSR XMX 和真实显卡；请先关闭 XMX 再改显卡身份": "XMX가 켜져 있으면 XeSS / FSR XMX와 실제 GPU를 유지합니다. GPU의 식별 정보를 바꾸기 전에 XMX를 끄세요.",
