    "此游戏已有外部 XMX 接入；保留原配置，暂不接管": "다른 도구에서 이 게임의 XMX를 관리합니다. 기존 설정은 그대로 두었습니다.",
    "需要已安装运行组件，并至少启动过一次该 Proton 游戏": "먼저 런타임 구성 요소를 설치하고 Proton으로 게임을 한 번 실행하세요.",
    "请选择检测到的游戏程序和接入方式": "검색된 게임 실행 파일과 설정 방법을 선택하세요.",
    "检测到自定义启动项，请先保留并清理，首版不自动合并": "사용자 지정 실행 옵션을 먼저 백업한 뒤 지우세요. 자동으로 병합할 수 없습니다.",
