    "首版需要主程序同目录已有 OptiScaler.ini 和 dxgi.dll": "OptiScaler.ini와 dxgi.dll은 게임 실행 파일과 같은 폴더에 있어야 합니다.",
    "dxgi.dll 未识别为 OptiScaler，保留原文件": "dxgi.dll을 OptiScaler 파일로 식별하지 못해 그대로 두었습니다.",
