    "启动项已被其他工具修改；保留改动，请先恢复本插件启动项再重试": "다른 도구가 실행 옵션을 변경했습니다. 변경 사항을 유지했습니다. 이 플러그인의 실행 옵션을 복원한 후 다시 시도하세요.",
    "文件已被游戏或其他工具修改，保留现场：": "게임이나 다른 도구가 파일을 변경해 그대로 두었습니다: ",
    "FSR 解压兼容组件清单无效，请重新安装插件。": "FSR 압축 해제 호환 구성 요소의 매니페스트가 유효하지 않습니다. 플러그인을 다시 설치하세요.",
    "FSR 解压兼容组件校验失败，请重新安装插件。": "FSR 압축 해제 호환 구성 요소를 검증하지 못했습니다. 플러그인을 다시 설치하세요.",
    "FSR 模型缓存记录无效，请重新导入。": "FSR 모델 캐시 기록이 유효하지 않습니다. 모델을 다시 가져오세요.",
