    "FSR 模型包在读取期间变化，请重试。": "읽는 동안 FSR 모델 패키지가 변경되었습니다. 다시 시도하세요.",
    "FSR 模型包 SHA-256 不匹配，请选择受支持的原始 ZIP。": "FSR 모델 패키지의 SHA-256이 일치하지 않습니다. 지원되는 원본 ZIP을 선택하세요.",
    "FSR 模型包文件列表不匹配。": "FSR 모델 패키지의 파일 목록이 일치하지 않습니다.",
