function normalizeLocale(value) {
    const [language, variant] = value.toLowerCase().replace(/_/g, '-').split('-');
    switch (language) {
        case 'schinese':
            return 'zh';
        case 'tchinese':
            return 'zh-TW';
        case 'zh':
            return ['hant', 'tw', 'hk', 'mo'].includes(variant) ? 'zh-TW' : 'zh';
        case 'japanese':
        case 'ja':
            return 'ja';
        case 'koreana':
        case 'korean':
        case 'ko':
            return 'ko';
        case 'german':
        case 'de':
            return 'de';
        case 'french':
        case 'fr':
            return 'fr';
        case 'spanish':
        case 'latam':
        case 'es':
            return 'es';
        default:
            return 'en';
    }
}
function queryLocale(search) {
    if (!search)
        return undefined;
    const query = new URLSearchParams(search);
    return query.get('l')?.trim()
        || query.get('lang')?.trim()
        || query.get('language')?.trim()
        || query.get('lng')?.trim();
}
function steamWindowLocale() {
    // The Steam window may be closing or inaccessible from this context.
    try {
        return queryLocale(globalThis.DFL?.findSP?.()?.location?.search);
    }
    catch {
        return undefined;
    }
}
function language() {
    const requested = queryLocale(typeof location === 'undefined' ? undefined : location.search)
        || steamWindowLocale()
        || (typeof document !== 'undefined' && document.documentElement.lang.trim())
        || (typeof navigator !== 'undefined' && navigator.language.trim())
        || 'en';
    return normalizeLocale(requested);
}
const catalogs = { de, en, es, fr, ja, ko, 'zh-TW': zhTW };
const english = en;
const prefixes = Object.keys(english).filter((key) => key.endsWith('：'));
function t(text) {
    const locale = language();
    if (locale === 'zh')
        return text;
    const key = Object.prototype.hasOwnProperty.call(english, text)
        ? text : prefixes.find((prefix) => text.startsWith(prefix));
    if (key === undefined)
        return text;
    const translated = catalogs[locale][key] || english[key] || key;
    return translated + text.slice(key.length);
}

const manifest = {"name":"Opti2XMX"};
const API_VERSION = 2;
